const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'cover', index: 1, title: 'VAPO: Value-Model-Based RL for Advanced Reasoning' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Decorative top bar
  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: '100%', h: 0.3, fill: { color: theme.primary } });

  slide.addText("VAPO: Value-Model-Based RL\nfor Advanced Reasoning", {
    x: 0.5, y: 1.5, w: 9, h: 1.5,
    fontSize: 40, fontFace: "Arial",
    color: theme.primary, bold: true, align: "center"
  });

  slide.addText("60.4 on AIME 2024", {
    x: 0.5, y: 3.0, w: 9, h: 0.8,
    fontSize: 32, fontFace: "Arial",
    color: theme.accent, bold: true, align: "center"
  });

  slide.addText("Authors: ByteDance Seed\nBase Model: Qwen2.5-32B", {
    x: 0.5, y: 4.0, w: 9, h: 1.0,
    fontSize: 20, fontFace: "Arial",
    color: theme.secondary, align: "center"
  });

  return slide;
}
module.exports = { createSlide, slideConfig };

