const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 2, title: 'Why Value Models?' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: '100%', h: 0.8, fill: { color: theme.primary } });
  slide.addText("Why Value Models? Finer Credit Assignment", {
    x: 0.5, y: 0.1, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Arial",
    color: "FFFFFF", bold: true
  });

  // Value-Model-Free box
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: 0.5, y: 1.2, w: 4.2, h: 3.5, fill: { color: theme.light }, rectRadius: 0.1 });
  slide.addText("Value-Model-Free (GRPO, DAPO)", {
    x: 0.5, y: 1.3, w: 4.2, h: 0.5,
    fontSize: 20, fontFace: "Arial", color: theme.primary, bold: true, align: "center"
  });
  slide.addText([
    { text: "• Uniform Credit Assignment: ", options: { bold: true } },
    { text: "Assigns advantage based on final trajectory reward uniformly across all tokens.\\n" },
    { text: "• Limitation for CoT: ", options: { bold: true } },
    { text: "Cannot trace each action's impact on returns.\\n" },
    { text: "• Vulnerability: ", options: { bold: true } },
    { text: "Subtle step-level errors can cause catastrophic failures without precise feedback." }
  ], { x: 0.7, y: 2.0, w: 3.8, h: 2.0, fontSize: 16, fontFace: "Arial", color: theme.secondary, bullet: true, margin: [10, 10, 10, 10] });

  // VS
  slide.addText("VS", { x: 4.7, y: 2.5, w: 0.6, h: 0.6, fontSize: 24, fontFace: "Arial", color: theme.accent, bold: true, align: "center" });

  // Value-Model-Based box
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: 5.3, y: 1.2, w: 4.2, h: 3.5, fill: { color: theme.primary }, rectRadius: 0.1 });
  slide.addText("Value-Model-Based (VAPO)", {
    x: 5.3, y: 1.3, w: 4.2, h: 0.5,
    fontSize: 20, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center"
  });
  slide.addText([
    { text: "• Precise Token-Level Credit: ", options: { bold: true } },
    { text: "Enables tracing each action's impact on final returns directly.\\n" },
    { text: "• Variance Reduction: ", options: { bold: true } },
    { text: "Provides lower-variance estimates per token compared to Monte Carlo methods.\\n" },
    { text: "• Better Generalization: ", options: { bold: true } },
    { text: "A well-trained value model generalizes across samples, improving sample efficiency." }
  ], { x: 5.5, y: 2.0, w: 3.8, h: 2.0, fontSize: 16, fontFace: "Arial", color: "FFFFFF", bullet: true, margin: [10, 10, 10, 10] });

  // Page number
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("2", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}
module.exports = { createSlide, slideConfig };

const pptxgen = require("pptxgenjs");

const slideConfig = { type: 'content', index: 3, title: 'Three Challenges' };

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  slide.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: '100%', h: 0.8, fill: { color: theme.primary } });
  slide.addText("Three Challenges in Value-Model-Based RL", {
    x: 0.5, y: 0.1, w: 9, h: 0.6,
    fontSize: 28, fontFace: "Arial",
    color: "FFFFFF", bold: true
  });

  slide.addText("Plaguing Value-Model-Based RL in Long-CoT Tasks", {
    x: 0.5, y: 0.9, w: 9, h: 0.5,
    fontSize: 20, fontFace: "Arial", color: theme.secondary, align: "center", bold: true
  });

  // Challenge 1
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: 0.5, y: 1.6, w: 2.8, h: 3.0, fill: { color: theme.light }, rectRadius: 0.1 });
  slide.addText("1", { x: 0.5, y: 1.8, w: 2.8, h: 0.5, fontSize: 36, fontFace: "Arial", color: theme.accent, bold: true, align: "center" });
  slide.addText("Value Model Bias", { x: 0.5, y: 2.4, w: 2.8, h: 0.5, fontSize: 18, fontFace: "Arial", color: theme.primary, bold: true, align: "center" });
  slide.addText("Stems from long trajectories and bootstrapped learning. Early errors compound over long reasoning chains.", {
    x: 0.7, y: 3.0, w: 2.4, h: 1.5, fontSize: 15, fontFace: "Arial", color: theme.secondary, align: "center"
  });

  // Challenge 2
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: 3.6, y: 1.6, w: 2.8, h: 3.0, fill: { color: theme.light }, rectRadius: 0.1 });
  slide.addText("2", { x: 3.6, y: 1.8, w: 2.8, h: 0.5, fontSize: 36, fontFace: "Arial", color: theme.accent, bold: true, align: "center" });
  slide.addText("Heterogeneous Lengths", { x: 3.6, y: 2.4, w: 2.8, h: 0.5, fontSize: 18, fontFace: "Arial", color: theme.primary, bold: true, align: "center" });
  slide.addText("Responses have highly variable lengths, requiring different bias-variance tradeoffs that standard methods fail to balance.", {
    x: 3.8, y: 3.0, w: 2.4, h: 1.5, fontSize: 15, fontFace: "Arial", color: theme.secondary, align: "center"
  });

  // Challenge 3
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, { x: 6.7, y: 1.6, w: 2.8, h: 3.0, fill: { color: theme.light }, rectRadius: 0.1 });
  slide.addText("3", { x: 6.7, y: 1.8, w: 2.8, h: 0.5, fontSize: 36, fontFace: "Arial", color: theme.accent, bold: true, align: "center" });
  slide.addText("Reward Sparsity", { x: 6.7, y: 2.4, w: 2.8, h: 0.5, fontSize: 18, fontFace: "Arial", color: theme.primary, bold: true, align: "center" });
  slide.addText("Only the final <eos> token receives a reward signal, exacerbated by long Chain-of-Thought (CoT) processes.", {
    x: 6.9, y: 3.0, w: 2.4, h: 1.5, fontSize: 15, fontFace: "Arial", color: theme.secondary, align: "center"
  });

  // Page number
  slide.addShape(pres.shapes.OVAL, { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fill: { color: theme.accent } });
  slide.addText("3", { x: 9.3, y: 5.1, w: 0.4, h: 0.4, fontSize: 12, fontFace: "Arial", color: "FFFFFF", bold: true, align: "center", valign: "middle" });

  return slide;
}
module.exports = { createSlide, slideConfig };

